import { useCallback, useState, type ReactNode } from 'react'
import { fetchArtifactText, paths, scopedResultPath, type RunScope, type WorkerResult } from '../api.ts'
import { AppLink, ErrorPanel, LoadingPanel } from '../panels.tsx'
import { runPathname } from '../routes.ts'
import { NodeSection } from '../SectionIndex.tsx'
import { evidenceOf } from './model.ts'
import { Time } from '../Time.tsx'
import { formatSpan, spanBetween } from '../time.ts'
import { useResource } from '../useResource.ts'
import { useRunResult } from '../useRunData.ts'
import { ResultError, ResultFacts } from './ResultFacts.tsx'
import './verify.css'

type Phase = 'worker' | 'candidate'

/** Text-like artifact kinds are shown as plain text on demand; screenshots are images; anything else is only listed. */
function TextArtifact({ scope, artifactId }: { scope: RunScope; artifactId: string }) {
  const [open, setOpen] = useState(false)
  const load = useCallback((signal: AbortSignal) => fetchArtifactText(scope, artifactId, signal), [scope, artifactId])
  const { state, reload } = useResource(open ? `artifact:${artifactId}` : null, load)
  return (
    <div className="artifact-text">
      <button type="button" className="button button-small" aria-expanded={open} onClick={() => setOpen(previous => !previous)}>
        {open ? 'Hide contents' : 'Show contents'}
      </button>
      {open && state.status === 'loading' && <LoadingPanel>Loading artifact {artifactId}…</LoadingPanel>}
      {open && state.status === 'error' && <ErrorPanel error={state.error} what={`Artifact ${artifactId}`} onRetry={reload} />}
      {open && state.status === 'ready' && (
        state.data.length === 0
          ? <p className="projects-muted">This artifact is empty.</p>
          : <pre className="artifact-log" data-testid={`artifact-text:${artifactId}`} tabIndex={0}>{state.data}</pre>
      )}
    </div>
  )
}

function ScreenshotArtifact({ scope, artifactId }: { scope: RunScope; artifactId: string }) {
  const [failed, setFailed] = useState(false)
  if (failed) return <p className="projects-error-inline" role="alert">Screenshot {artifactId} could not be loaded from the artifact route.</p>
  return (
    <img
      className="artifact-screenshot"
      src={paths.artifact(scope, artifactId)}
      alt={`Screenshot artifact ${artifactId}`}
      data-testid={`artifact-screenshot:${artifactId}`}
      onError={() => setFailed(true)}
    />
  )
}

/**
 * What the trusted verifier proved, on a verify node and for each lane of the combined candidate: the gate with the
 * reasons it recorded and its deferred checks, the checks with their logs, screenshots, other artifacts and the result's
 * facts. Empty sections are absent. On the verify node (`anchored`) each block is a section of the page's index; a
 * candidate lane keeps them inside its lane. Captured files are the launch node's; they are not repeated here.
 */
export function VerifiedEvidence({ scope, result, phase, testId = 'worker-result', anchored = false }: { scope: RunScope; result: WorkerResult; phase: Phase; testId?: string; anchored?: boolean }) {
  const { artifactsById, screenshots, others, deferred, passed } = evidenceOf(result)
  const block = (key: string, title: string, children: ReactNode, extra: { testId?: string; passed?: boolean } = {}) => anchored ? (
    <NodeSection key={key} sectionKey={key} title={title} testId={extra.testId} className="evidence-section">
      {children}
    </NodeSection>
  ) : (
    <section key={key} className="evidence-section" aria-labelledby={`${testId}-${key}`} data-testid={extra.testId}>
      <h4 id={`${testId}-${key}`}>{title}</h4>
      {children}
    </section>
  )
  return (
    <div className="worker-evidence" data-testid={testId} data-view="verified">
      <div className="gate-block" data-testid="gate-outcome" data-passed={passed ? 'true' : 'false'}>
        {block('gate', 'Gate', (
          <>
            <ResultError result={result} />
            <p>
              {passed
                ? `Passed: every gating check of this ${phase === 'worker' ? 'isolated lane snapshot' : 'combined candidate'} exited 0.`
                : 'Did not pass: see the error above for the reasons the gate recorded.'}
            </p>
            {deferred.size > 0 && (
              <p className="projects-notice-inline" data-testid="deferred-checks">
                Deferred checks: {[...deferred.values()].join(', ')} — executed and recorded on this isolated lane snapshot, but gated only at the combined candidate, which verifies the whole application.
              </p>
            )}
            <p className="projects-muted" data-testid="ownership-outcome">
              {phase === 'candidate'
                ? 'Ownership: enforced on each lane\'s isolated snapshot, not on the combined candidate.'
                : passed
                  ? 'Ownership: the verifier checked the changed files against the lane\'s owned paths on this snapshot, and the gate passed.'
                  : 'Ownership: checked on this snapshot; an ownership violation, if there was one, is among the reasons in the error above.'}
            </p>
          </>
        ))}
      </div>

      {result.checks.length > 0 && block('checks', 'Checks actually executed', (
        <ul className="evidence-list" data-testid="checks-list">
          {result.checks.map((check, index) => {
            const log = artifactsById.get(check.log_artifact_id)
            const isDeferred = deferred.has(index)
            const exitText = check.exit_code === 0 ? 'exit 0' : `exit ${check.exit_code}`
            const took = spanBetween(check.started_at, check.finished_at)
            return (
              <li key={`${check.log_artifact_id}-${index}`} id={`check-${index}`} tabIndex={-1} className={isDeferred ? 'check check-deferred' : check.exit_code === 0 ? 'check check-passed' : 'check check-failed'} data-exit-code={check.exit_code} data-deferred={isDeferred ? 'true' : undefined}>
                <div className="check-head">
                  <code className="check-command">{check.command}</code>
                  <span className="check-exit">{isDeferred ? `${exitText} · recorded, gated at the combined candidate` : check.exit_code === 0 ? exitText : `${exitText} (failed)`}</span>
                </div>
                <p className="projects-muted check-meta">
                  <Time iso={check.started_at} seconds /> → <Time iso={check.finished_at} seconds />
                  {took !== null && <> · <span className="check-duration">{formatSpan(took)}</span></>} · cwd <code>{check.cwd}</code>
                </p>
                <div className="check-log">
                  <span>Log artifact <code>{check.log_artifact_id}</code>{log ? '' : ' (not listed among the result artifacts)'}</span>
                  {log && <TextArtifact scope={scope} artifactId={log.artifact_id} />}
                </div>
              </li>
            )
          })}
        </ul>
      ))}

      {(screenshots.length > 0 || deferred.size > 0) && block('screenshots', 'Screenshots', screenshots.length === 0 ? (
        <p className="projects-muted" data-testid="screenshots-deferred">No screenshot artifacts were published for this isolated lane run; browser evidence is gated and shown at the combined candidate.</p>
      ) : (
        <ul className="evidence-list evidence-screenshots" data-testid="screenshots">
          {screenshots.map(artifact => (
            <li key={artifact.artifact_id}>
              <p><code>{artifact.artifact_id}</code> <span className="projects-muted">sha256 {artifact.sha256.slice(0, 12)}…</span></p>
              <ScreenshotArtifact scope={scope} artifactId={artifact.artifact_id} />
            </li>
          ))}
        </ul>
      ))}

      {others.length > 0 && block('artifacts', 'Other artifacts', (
        <ul className="evidence-list" data-testid="artifacts">
          {others.map(artifact => (
            <li key={artifact.artifact_id}>
              <p><code>{artifact.artifact_id}</code> · {artifact.kind} · <span className="projects-muted">sha256 {artifact.sha256.slice(0, 12)}…</span></p>
              {artifact.kind === 'other'
                ? <p className="projects-muted">Not rendered: only logs, reports, patches and screenshots are displayed.</p>
                : <TextArtifact scope={scope} artifactId={artifact.artifact_id} />}
            </li>
          ))}
        </ul>
      ))}

      {block('result', 'Result', <ResultFacts result={result} />)}
    </div>
  )
}

/** "Worker's report → Launch ui worker ›": where a verified result's worker narrative lives, said once (docs/PRD_VIEWER_UX.md 7). */
export function WorkerReportLink({ href, label, onNavigate }: { href: string; label: string; onNavigate: (pathname: string) => void }) {
  return (
    <p className="worker-report-link" data-testid="worker-report-link">
      Worker's report → <AppLink href={href} onNavigate={onNavigate}>{label} ›</AppLink>
    </p>
  )
}

export type LaneEntry = { worker: string; attempt: number; result_uri: string }

/** One lane's result of the combined candidate, read through the run's cache of immutable results. */
function LaneResult({ scope, lane, launchNode, stamp, onNavigate }: {
  scope: RunScope
  lane: LaneEntry
  /** The graph node that launched the lane, which shows the files it created and its report; null when the pinned graph has none. */
  launchNode: { node_id: string; label: string } | null
  stamp: string
  onNavigate: (pathname: string) => void
}) {
  const resultPath = scopedResultPath(scope, lane.result_uri)
  const { state, reload } = useRunResult(scope, resultPath, stamp)
  return (
    <section className="lane-result" aria-label={`Lane ${lane.worker}`} data-testid={`lane-result:${lane.worker}`}>
      <h5>Lane {lane.worker} <span className="projects-muted">· candidate attempt {lane.attempt}</span></h5>
      {launchNode !== null && (
        <>
          <p className="projects-muted" data-testid="lane-files-link">
            Files are captured on the lane's worker snapshot only:{' '}
            <AppLink href={runPathname(scope.projectId, scope.workflowId, scope.runId, launchNode.node_id)} onNavigate={onNavigate}>open the files the {lane.worker} lane created or changed</AppLink>.
          </p>
          <WorkerReportLink href={runPathname(scope.projectId, scope.workflowId, scope.runId, launchNode.node_id)} label={launchNode.label} onNavigate={onNavigate} />
        </>
      )}
      {resultPath === null && (
        <p className="projects-error-inline" role="alert">The result link <code>{lane.result_uri}</code> is outside this run's results route and was not fetched.</p>
      )}
      {resultPath !== null && state.status === 'loading' && <LoadingPanel>Loading the {lane.worker} lane result…</LoadingPanel>}
      {resultPath !== null && state.status === 'error' && <ErrorPanel error={state.error} what={`The ${lane.worker} lane result`} onRetry={reload} />}
      {resultPath !== null && state.status === 'ready' && <VerifiedEvidence scope={scope} result={state.data} phase="candidate" testId={`lane-result-evidence:${lane.worker}`} />}
    </section>
  )
}

/** The combined candidate's lanes: every lane verified on one revision, each with its checks and screenshots. */
export function CandidateLanes({ scope, lanes, launchNodeOf, stamp, onNavigate }: {
  scope: RunScope
  lanes: LaneEntry[]
  launchNodeOf: (lane: string) => { node_id: string; label: string } | null
  stamp: string
  onNavigate: (pathname: string) => void
}) {
  return (
    <NodeSection sectionKey="lanes" title="Lanes">
      <div className="lane-results" data-testid="lane-results">
        <p className="projects-muted">The combined candidate verified every lane on one revision; each lane's result, with its checks and screenshots, is shown below.</p>
        {lanes.map(lane => (
          <LaneResult key={lane.worker} scope={scope} lane={lane} launchNode={launchNodeOf(lane.worker)} stamp={stamp} onNavigate={onNavigate} />
        ))}
      </div>
    </NodeSection>
  )
}

/* ---- Verification and candidate sections (docs/PRD_VIEWER_UX.md 4.6) ---- */

.worker-report-link { margin: 0; font-size: 0.85rem; color: var(--text-muted); }
.lane-result .worker-report-link { margin-bottom: 8px; }

import type { WorkerResult } from '../api.ts'
import { StatusBadge } from '../panels.tsx'

function shortSha(value: string | null): string {
  return value === null ? 'none' : value.slice(0, 12)
}

/**
 * The facts that anchor a result to its snapshot: status, attempt, session and commits. When a launch node and a verify
 * node link the same result they are shown once, on the verify node (docs/PRD_VIEWER_UX.md 7).
 */
export function ResultFacts({ result }: { result: WorkerResult }) {
  return (
    <dl className="projects-facts" data-testid="result-facts">
      <div><dt>Result status</dt><dd><StatusBadge status={result.status} /></dd></div>
      <div><dt>Attempt</dt><dd>{result.attempt}</dd></div>
      <div><dt>Session</dt><dd><code>{result.session_id}</code></dd></div>
      <div><dt>Base commit</dt><dd><code>{shortSha(result.base_commit)}</code></dd></div>
      <div><dt>Output commit</dt><dd>{result.output_commit ? <code>{shortSha(result.output_commit)}</code> : 'None recorded (no durable output commit)'}</dd></div>
    </dl>
  )
}

/** The error the result recorded: the gate's reasons on a verification, shown with the facts. */
export function ResultError({ result }: { result: WorkerResult }) {
  if (!result.error) return null
  return (
    <div className="projects-error" role="alert" data-testid="worker-error">
      <p><strong>Error {result.error.code}:</strong> {result.error.message}</p>
      <p>{result.error.retryable ? 'Marked retryable by the producer. Retrying is done through the workflow CLI, not this viewer.' : 'Marked not retryable by the producer.'}</p>
    </div>
  )
}

/**
 * The worker's narrative in its result: the summary and the open assumptions behind a count, absent when there are none. Shown
 * once, on the launch node, when it shares the result with its verify node.
 */
export function WorkerNarrative({ result }: { result: WorkerResult }) {
  return (
    <>
      <p className="worker-summary" data-testid="worker-summary">{result.summary}</p>
      {result.open_assumptions.length > 0 && (
        <details className="evidence-section assumptions-details" data-testid="assumptions-details">
          <summary id="evidence-assumptions">Open assumptions ({result.open_assumptions.length})</summary>
          <ul className="evidence-list" data-testid="assumptions">
            {result.open_assumptions.map((assumption, index) => <li key={index}>{assumption}</li>)}
          </ul>
        </details>
      )}
    </>
  )
}
import type { RunInputWorker, WorkerResult } from '../api.ts'
import { AppLink } from '../panels.tsx'
import { formatDuration } from '../status.ts'
import type { Resource } from '../useResource.ts'

/** Where a check id named by the worker is shown: the verify node, and the executed check it matched by command when known. */
export type CheckTarget = { href: string; label: string }

/** The paths the lane may change, as pinned in the run plan. */
export function OwnedPaths({ paths }: { paths: RunInputWorker['owned_paths'] }) {
  return (
    <>
      <h5 id="task-owned-title">Owned paths</h5>
      {paths.length === 0 ? (
        <p className="projects-muted">No owned paths were pinned.</p>
      ) : (
        <ul className="evidence-list evidence-files" data-testid="task-owned-paths" aria-labelledby="task-owned-title">
          {paths.map(path => <li key={path}><code>{path}</code></li>)}
        </ul>
      )}
    </>
  )
}

/**
 * The lane's required checks: the check kinds it must pass and each declared check, matched to the executed checks of the
 * published result by exact command; a match links to the verify node that shows the check with its log.
 */
export function RequiredChecks({ worker, result, checksNode, onNavigate }: {
  worker: RunInputWorker
  /** The node's published result, when it loaded: required checks are matched to executed checks by exact command. */
  result: Resource<WorkerResult>
  /** The verify node that shows the executed checks with their logs; null when the pinned graph has none. */
  checksNode: CheckTarget | null
  onNavigate: (pathname: string) => void
}) {
  const executed = result.status === 'ready' ? result.data.checks : null
  return (
    <>
      <h5 id="task-checks-title">Required checks</h5>
      <p className="projects-muted" data-testid="task-required-kinds">
        Required check kinds for this lane: {worker.required_check_kinds.length === 0 ? 'none pinned' : worker.required_check_kinds.join(', ')}
      </p>
      {worker.checks.length === 0 ? (
        <p className="projects-muted">No checks were required.</p>
      ) : (
        <ul className="evidence-list task-checks" data-testid="task-checks" aria-labelledby="task-checks-title">
          {worker.checks.map(check => {
            const executedIndex = executed === null ? -1 : executed.findIndex(candidate => candidate.command === check.command)
            return (
              <li key={check.id} data-check-id={check.id}>
                <code>{check.command}</code>
                <span className="projects-muted"> · {check.id} · {check.kind} · timeout {formatDuration(check.timeout_seconds)}</span>
                {check.scenarios.length > 0 && (
                  <span className="projects-muted"> · {check.scenarios.length} {check.scenarios.length === 1 ? 'scenario' : 'scenarios'}: {check.scenarios.map(scenario => scenario.id).join(', ')}</span>
                )}
                <div className="task-check-status">
                  {executed === null ? (
                    <span className="projects-muted">{result.status === 'loading' ? 'Loading the published result to compare…' : 'No published result to compare against.'}</span>
                  ) : executedIndex === -1 ? (
                    <span className="projects-muted">not executed in this result</span>
                  ) : checksNode === null ? (
                    <span>executed as check {executedIndex + 1}: exit {executed[executedIndex].exit_code}</span>
                  ) : (
                    <AppLink href={checksNode.href} onNavigate={onNavigate} data-check-index={executedIndex} title={`The check and its log are shown on ${checksNode.label}`}>
                      executed as check {executedIndex + 1}: exit {executed[executedIndex].exit_code} (on {checksNode.label})
                    </AppLink>
                  )}
                </div>
              </li>
            )
          })}
        </ul>
      )}
    </>
  )
}
import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { attemptResultUris, type Now, type Timeline } from '../../contracts/projects/triage.ts'
import { scopedResultPath, type RunDetail, type RunInputs, type ReviewResult, type RunScope, type WorkerResult, type WorkflowEvent } from './api.ts'
import { ChallengeSections } from './node/ChallengeSections.tsx'
import { AwaitingNotice, ControllerSections } from './node/ControllerSections.tsx'
import { attemptStrip, causeOf, nodeTiming, resultRole, revisionAttempt, verifiedSections, workerSectionEntries, type SectionEntry } from './node/model.ts'
import { ReviewSections } from './node/ReviewSections.tsx'
import { CandidateLanes, VerifiedEvidence, WorkerReportLink, type LaneEntry } from './node/VerifySections.tsx'
import { WorkerSections } from './node/WorkerSections.tsx'
import { NodeHeader } from './NodeHeader.tsx'
import { AppLink, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { attemptPathname, runPathname } from './routes.ts'
import { NodeSection, SectionIndex } from './SectionIndex.tsx'
import { isChallengeNode } from './status.ts'
import { Time } from './Time.tsx'
import type { Resource } from './useResource.ts'
import { useRunResult, useRunResults } from './useRunData.ts'
import './node.css'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type ReviewTransport = ReviewResult['reviewer']['transport']

type Props = {
  scope: RunScope
  detail: RunDetail
  definition: DefinitionNode
  node: SnapshotNode
  /** The attempt the path names (`/attempts/<k>`); null shows the latest. */
  attempt: number | null
  events: Resource<WorkflowEvent[]>
  onRetryEvents: () => void
  /** The run's inputs (null once loaded when the export predates them), shared by every node of the run. */
  inputs: Resource<RunInputs | null>
  onRetryInputs: () => void
  /** The run's timeline, once its events loaded: the header's times, attempts and markers. */
  timeline: Timeline | null
  /** The run's situation, once derived: its next step is repeated on the focus node. */
  now: Now | null
  clock: number
  refreshToken: number
  onNavigate: (pathname: string) => void
  /** A requirement quote to highlight in this node's task, handed over by a review finding link. */
  highlight: string | null
  onHighlightApplied: () => void
  onOpenRequirement: (nodeId: string, quote: string) => void
  /** A captured file to scroll to on this launch node, handed over by a review finding's file link. */
  fileFocus: string | null
  onFileFocusApplied: () => void
  onOpenFile: (nodeId: string, path: string) => void
}

/**
 * One node of a run (docs/PRD_VIEWER_UX.md 4.4-4.9): the header (status by cause, timing, attempts, next step), a section
 * index with counts, then the sections of its kind (worker, verification, candidate, review, challenge or the controller's
 * own steps) and History, always last. Empty sections are absent; a result the launch and verify nodes share is said once.
 * An earlier attempt's page shows that attempt's own result under a banner that leads back to the latest.
 */
export function NodeDetail({ scope, detail, definition, node, attempt, events, onRetryEvents, inputs, onRetryInputs, timeline, now, clock, refreshToken, onNavigate, highlight, onHighlightApplied, onOpenRequirement, fileFocus, onFileFocusApplied, onOpenFile }: Props) {
  const definitionNodes = detail.definition.nodes
  const snapshotNodes = detail.snapshot.nodes
  // A review's executor wording depends on the transport its served result records, known once the review panel loads it.
  const [reviewTransport, setReviewTransport] = useState<ReviewTransport | undefined>(undefined)

  const isWorker = definition.kind === 'worker'
  const isChallenge = isChallengeNode(definition)
  const isReview = definition.kind === 'review' && !isChallenge
  const isCandidate = node.node_id === 'candidate'
  const isVerify = definition.kind === 'verification' && !isCandidate
  const isController = definition.kind === 'prepare' || definition.kind === 'integration'
  const latest = node.attempt
  const isLatest = attempt === null || attempt === latest
  const shownAttempt = attempt ?? latest
  const recorded = shownAttempt >= 1 && shownAttempt <= latest

  // What this view reads: the latest attempt's result as served, or the viewed attempt's own (`results/<lane>/<k>`).
  const attemptUris = useMemo(() => attemptResultUris(detail, node.node_id), [detail, node.node_id])
  const resultUri = definition.kind === 'review' ? null
    : isLatest || !isVerify ? node.result_uri
      : attemptUris.find(item => item.attempt === attempt)?.uri ?? null
  const lanes: LaneEntry[] = isLatest || !isCandidate ? node.lane_results
    : attemptUris.filter(item => item.attempt === attempt).map(item => ({ worker: item.lane, attempt: item.attempt, result_uri: item.uri }))
  const resultPath = resultUri === null ? null : scopedResultPath(scope, resultUri)
  const stamp = String(refreshToken)
  const { state: result, reload: reloadResult } = useRunResult(scope, resultPath, stamp)
  const resultData = result.status === 'ready' ? result.data : null

  // The attempt strip: a chip shows once one of its results loaded (read through the run's cache, asked again on new events).
  const strip = useMemo(() => (timeline ? attemptStrip(detail, timeline, node.node_id) : []), [detail, timeline, node.node_id])
  const chipUris = useMemo(() => strip.flatMap(item => (item.kind === 'attempt' ? item.chip.uris : [])), [strip])
  const { results: chipResults } = useRunResults(scope, chipUris, `${refreshToken}:${detail.snapshot.last_sequence}`)
  const loaded = useCallback((uri: string) => chipResults.has(uri), [chipResults])
  const viewedChip = strip.flatMap(item => (item.kind === 'attempt' && item.chip.attempt === shownAttempt ? [item.chip] : []))[0]

  // The candidate's own verdict is its lanes': a failing lane's gate reasons are the cause its header names.
  const { results: laneResults } = useRunResults(scope, useMemo(() => lanes.map(entry => entry.result_uri), [lanes]), stamp)
  const failure = lanes.flatMap(entry => {
    const error = laneResults.get(entry.result_uri)?.error
