  { phase: 'worker', lane: 'ui', attempt: 2, from: '09:21:35', to: '09:23:35' },
  { phase: 'worker', lane: 'adapter', attempt: 2, from: '09:21:35', to: '09:22:35' },
  { phase: 'candidate', lane: 'ui', attempt: 1, from: '09:23:45', to: '09:25:55' },
