            >
              Files and report ›
            </AppLink>
          </span>
        )}
      </summary>
      <VerifiedEvidence scope={scope} result={result} phase="candidate" testId={`lane-result-evidence:${lane.worker}`} declared={declared} attemptStart={attemptStart} />
    </details>
  )
}

/**
